      if (!ctx || !ctx.eventSource || !ctx.eventSource.on) return;
      // 事件字面量是 'chat_id_changed'（event_types.CHAT_CHANGED），别写成 'chat_changed'
      var ev = (ctx.eventTypes && ctx.eventTypes.CHAT_CHANGED) || 'chat_id_changed';
